"use client";
import { useState } from "react";

export default function Home() {
  const [count, setCount] = useState(0);
  return (
    <div className="min-h-screen bg-[#0a0a0f] text-white p-8">
      <h1 className="text-2xl font-bold">Next.js 14 App - AI Provider OS Template</h1>
      <p className="text-slate-400 mt-2">Você cria orientando AI</p>
      <div className="mt-6 p-4 rounded-xl bg-[#11111b] border border-[#1e1e2e]">
        <div className="text-4xl font-bold">{count}</div>
        <div className="flex gap-2 mt-4">
          <button onClick={() => setCount(c => c - 1)} className="px-4 py-2 rounded-lg bg-[#1a1a2a] border border-[#2a2a3e]">-</button>
          <button onClick={() => setCount(c => c + 1)} className="px-4 py-2 rounded-lg bg-white text-black">+</button>
        </div>
      </div>
    </div>
  );
}

